}

function addPauser(address user) external onlyOwner {
isPauser[user] = true;
}

function removePauser(address user) external onlyOwner {
isPauser[user] = false;
}

modifier onlyPauser {
require(isPauser[msg.sender], "Not a Pauser");
_;
}

