return IERC20(upgradedAddress).totalSupply();
}
return _totalSupply;
}

function _approve(
address account,
address spender,
uint256 amount
) private notOnBlacklist(account) notOnBlacklist(spender) notPaused {
_allowances[account][spender] = amount;
