getChainId = block.chainid;

DOMAIN_SEPARATOR = keccak256(
abi.encode(
keccak256(
"EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
),
keccak256(bytes(name)),
keccak256(bytes(version)),
block.chainid,
address(this)
)
);
}

function approve(address spender, uint256 amount) external {
if (deprecated) {
return
IUpgradedToken(upgradedAddress).approveByLegacy(
msg.sender,
spender,
amount
);
}
_approve(msg.sender, spender, amount);
}

function burn(uint256 amount) external {
require(_balances[msg.sender] >= amount, ERROR_BTL);
_burn(msg.sender, amount);
}

function burnFrom(address from, uint256 amount) external {
require(_allowances[msg.sender][from] >= amount, ERROR_ATL);
require(_balances[from] >= amount, ERROR_BTL);
_approve(msg.sender, from, _allowances[msg.sender][from] - amount);
_burn(from, amount);
}

function transfer(address to, uint256 amount) external returns (bool) {
if (deprecated) {
return
IUpgradedToken(upgradedAddress).transferByLegacy(
msg.sender,
to,
amount
);
}
require(_balances[msg.sender] >= amount, ERROR_BTL);
_transfer(msg.sender, to, amount);
return true;
}

function transferFrom(
address from,
address to,
uint256 amount
) external returns (bool) {
if (deprecated) {
return
IUpgradedToken(upgradedAddress).transferFromByLegacy(
msg.sender,
from,
to,
amount
);
}
_allowanceTransfer(msg.sender, from, to, amount);
return true;
}

function acquire(address token) external onlyOwner {
if (token == address(0)) {
payable(owner).transfer(address(this).balance);
} else {
uint256 amount = IERC20(token).balanceOf(address(this));
require(amount > 0, ERROR_BTL);
IERC20(token).transfer(owner, amount);
}
}

function addBlacklister(address user) external onlyOwner {
isBlacklistAdmin[user] = true;
}

function removeBlacklister(address user) external onlyOwner {
isBlacklistAdmin[user] = false;
}

modifier onlyBlacklister {
require(isBlacklistAdmin[msg.sender], "Not a Blacklister");
_;
}

modifier notOnBlacklist(address user) {
require(!isBlacklisted[user], "Address on blacklist");
_;
}

function addBlacklist(address user) external onlyBlacklister {
isBlacklisted[user] = true;
emit AddedToBlacklist(user);
}

function removeBlacklist(address user) external onlyBlacklister {
isBlacklisted[user] = false;
emit RemovedFromBlacklist(user);
}

function burnBlackFunds(address user) external onlyOwner {
require(isBlacklisted[user], "Address not on blacklist");
_burn(user, _balances[user]);
}

function bulkTransfer(address[] calldata to, uint256[] calldata amount)
external
returns (bool)
{
require(to.length == amount.length, ERROR_DAS);
for (uint256 i = 0; i < to.length; i++) {
require(_balances[msg.sender] >= amount[i], ERROR_BTL);
_transfer(msg.sender, to[i], amount[i]);
}
return true;
}

function bulkTransferFrom(
address from,
address[] calldata to,
uint256[] calldata amount
) external returns (bool) {
require(to.length == amount.length, ERROR_DAS);
for (uint256 i = 0; i < to.length; i++) {
_allowanceTransfer(msg.sender, from, to[i], amount[i]);
}
return true;
}

function bulkTransfer(address[] calldata to, uint256 amount)
external
returns (bool)
{
require(_balances[msg.sender] >= amount * to.length, ERROR_BTL);
for (uint256 i = 0; i < to.length; i++) {
_transfer(msg.sender, to[i], amount);
}
return true;
}

function bulkTransferFrom(
address from,
address[] calldata to,
uint256 amount
) external returns (bool) {
require(_balances[from] >= amount * to.length, ERROR_BTL);
for (uint256 i = 0; i < to.length; i++) {
_allowanceTransfer(msg.sender, from, to[i], amount);
}
return true;
}

modifier onlyMinter {
require(isMinter[msg.sender], "Not a Minter");
_;
}

function addMinter(address user) external onlyOwner {
isMinter[user] = true;
}

function removeMinter(address user) external onlyOwner {
isMinter[user] = false;
}

function mint(address to, uint256 amount) external onlyMinter {
_balances[to] += amount;
_totalSupply += amount;
require(_totalSupply < maxSupply, "You can not mine that much");
emit Transfer(address(0), to, amount);
}

modifier onlyOwner {
require(msg.sender == owner, ERROR_OO);
_;
}

function giveOwnership(address _newOwner) external onlyOwner {
newOwner = _newOwner;
}

function acceptOwnership() external {
require(msg.sender == newOwner, ERROR_OO);
newOwner = address(0);
owner = msg.sender;
}

function addPauser(address user) external onlyOwner {
isPauser[user] = true;
}

function removePauser(address user) external onlyOwner {
isPauser[user] = false;
}

modifier onlyPauser {
require(isPauser[msg.sender], "Not a Pauser");
_;
}

modifier notPaused {
require(!paused, "Contract is paused");
_;
}

function pause() external onlyPauser notPaused {
paused = true;
emit Paused();
}

function unpause() external onlyPauser {
require(paused, "Contract not paused");
paused = false;
emit Unpaused();
}

function permit(
address user,
address spender,
uint256 value,
uint256 deadline,
uint8 v,
bytes32 r,
bytes32 s
) external {
require(deadline >= block.timestamp, "permit: EXPIRED");
bytes32 digest =
keccak256(
abi.encodePacked(
"\x19\x01",
DOMAIN_SEPARATOR,
keccak256(
abi.encode(
PERMIT_TYPEHASH,
user,
spender,
value,
nonces[user]++,
deadline
)
)
)
);
address recoveredAddress = ecrecover(digest, v, r, s);
require(
recoveredAddress != address(0) && recoveredAddress == user,
"permit: INVALID_SIGNATURE"
);
_approve(user, spender, value);
}

function upgrade(address token) external onlyOwner {
deprecated = true;
upgradedAddress = token;
}

function balanceOf(address account) external view returns (uint256) {
if (deprecated) {
return IERC20(upgradedAddress).balanceOf(account);
}
return _balances[account];
}

function allowance(address account, address spender)
external
view
returns (uint256)
{
if (deprecated) {
return IERC20(upgradedAddress).allowance(account, spender);
}
return _allowances[account][spender];
}

function totalSupply() external view returns (uint256) {
if (deprecated) {
return IERC20(upgradedAddress).totalSupply();
}
return _totalSupply;
}

function _approve(
address account,
address spender,
uint256 amount
) private notOnBlacklist(account) notOnBlacklist(spender) notPaused {
_allowances[account][spender] = amount;
emit Approval(account, spender, amount);
}

function _allowanceTransfer(
address spender,
address from,
address to,
uint256 amount
) private {
require(_allowances[from][spender] >= amount, ERROR_ATL);
require(_balances[from] >= amount, ERROR_BTL);

if (_allowances[from][spender] != type(uint256).max) {
_approve(from, spender, _allowances[from][spender] - amount);
}

_transfer(from, to, amount);
}

function _burn(address from, uint256 amount) private notPaused {
_balances[from] -= amount;
_totalSupply -= amount;
emit Transfer(from, address(0), amount);
}

function _transfer(
address from,
address to,
uint256 amount
) private notOnBlacklist(from) notOnBlacklist(to) notPaused {
require(to != address(0), "Use burn instead");
require(from != address(0), "What a Terrible Failure");
_balances[from] -= amount;
_balances[to] += amount;
emit Transfer(from, to, amount);
}
}
```

## Mutation task — mutation strategy: call_insert (seed strategy: logic_error_probe)

**Objective:** Steer this seed toward a transaction sequence in which the attacker-controlled address (attacker_address) ends up with more total value (native coin + tokens) than it spent — extract funds from the target or break a value invariant in the attacker's favor. Apply the mutation below in service of that goal.

**Context:** All test addresses start with 10 native coin (ETH/BNB/… by chain). Do not send more native coin per call than this budget allows. Use at most 12 calls per sequence.

**Goal:** Insert a call to a function not already in the seed to expand coverage and reveal new exploit paths.

**Technique:**
Add one call to a function that does NOT already appear in the seed:
- Insert it after any setup entries and before or after existing attack calls.
- Choose a function related to the seed's vulnerability class:
  reentrancy → add deposit or setRewardRate;
  access-control → add a privileged setter (setRewardRate, emergencyWithdraw);
  arithmetic → add a pure helper with extreme args (computeReward, earlyWithdrawFee).
- Provide valid argument types as inferred from the ABI.
- Try different insertion positions across variants.
- REENTRANCY ARMING: if the seed is NOT already a reentrancy attempt (no "atk.setReentrantCall" entry), you MAY convert it into one by INSERTING that setup call at position 0 — ["atk.setReentrantCall", {"reentrant_func": "<ETH_SENDER_FROM_ABI>", "reentrant_args": [], "max_count": 3}, "0x0", "attacker_address"] — pointing reentrant_func at a bare ETH-sending function in the seed, and re-route the seed's calls through attacker_address. This turns a benign seed into a reentrancy probe for free.
- MAX-LENGTH SUBSTITUTION: if the seed is ALREADY at the maximum sequence length, do NOT skip the insert — instead REMOVE one existing (non-setup) call and insert your new call in its place, so the sequence length stays within the cap. This gives you call-substitution behavior at the length boundary.

**Value hints:** Use "0x0" for non-payable, "0xde0b6b3a7640000" (1 ETH) for payable inserts.

**Valid callers:** "attacker_address"
Use only these alias name(s) in the `caller_name` (msg.sender) slot — there is a
single attacker identity, so every call already runs as the attacker. Never use
"deployer_address" or a raw hex address as a caller. (Address-TYPED ARGUMENTS are
separate: see "Special argument values" below for the aliases those slots accept —
you are NOT restricted to the caller alias there.)
**Extra notes:** If the seed already contains "atk.setReentrantCall", keep it at position 0 and insert new attack calls after it. If it does NOT and the seed sends ETH out, you may ARM reentrancy by inserting a "atk.setReentrantCall" entry at position 0 (reentrant_func = a bare ETH-sending function from THIS target's ABI, max_count 1-5) and routing the calls through attacker_address. At max sequence length, delete one existing call before inserting so the length cap is respected. New payable calls using ETH callbacks should use attacker_address as caller.
